INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('芡实','平','甘/涩','脾/肾','益肾固精，补脾止泻，除湿止带','9-15','大小便不利者禁服，食滞不化者慎服');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('荷叶','平','苦','肝/脾/胃','清暑化湿，升发清阳，凉血止血','3-10','气血虚者慎服');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('椿皮','寒','苦/涩','大肠/肝','清热燥湿，收涩止带，止泻，止血','6-9','脾胃虚寒者慎用');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('金樱子','平','酸/甘/涩','肾/膀胱/大肠','固精缩尿，固崩止带，涩肠止泻','6-12','有实火、实邪者不宜服');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('刺猬皮','平','苦/涩','肾/胃/大肠','固精缩尿，收敛止血，化瘀止痛','3-10(研末1.5-3)','孕妇慎用');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('莲子心','寒','苦','心/肾','清心安神，交通心肾，涩精止血','2-5','脾胃虚寒者禁服');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('麻黄根','平','甘/涩','心/肺','固表止汗','3-9','有表邪者忌用');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('浮小麦','凉','甘','心','益气，除热，止汗','15-30','表邪汗出者忌用');
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('糯稻根须','平','甘','心/肝','固表止汗，益胃生津，退虚热','15-30',NULL);
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('五味子(醋)','温','酸','肺/心/肾','收敛固涩，补肾宁心(醋制增强收敛)','2-6',NULL);
INSERT INTO knowledge.tcm_herbs(herb_name,nature,flavor,meridian,effects,dosage,caution) VALUES ('石榴皮(炭)','温','酸/涩','大肠','涩肠止泻止血(炭制)','3-9',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('麻黄汤','《伤寒论》','麻黄、桂枝、杏仁、炙甘草','发汗解表，宣肺平喘','外感风寒表实证(恶寒发热、无汗而喘)','表虚自汗、血虚、阴虚忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('桂枝汤','《伤寒论》','桂枝、芍药、生姜、大枣、炙甘草','解肌发表，调和营卫','外感风寒表虚证(发热汗出、恶风)','温服、啜热稀粥以助药力');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('九味羌活汤','《此事难知》','羌活、防风、苍术、细辛、川芎、白芷、生地黄、黄芩、甘草','发汗祛湿，兼清里热','外感风寒湿邪兼有里热证','风热表证不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('小青龙汤','《伤寒论》','麻黄、芍药、细辛、干姜、炙甘草、桂枝、五味子、半夏','解表散寒，温肺化饮','外寒内饮证(咳喘痰多清稀)','阴虚干咳无痰者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('止嗽散','《医学心悟》','紫菀、百部、白前、桔梗、荆芥、陈皮、甘草','宣利肺气，疏风止咳','风邪犯肺之咳嗽(表邪未尽)','阴虚劳嗽者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('银翘散','《温病条辨》','金银花、连翘、薄荷、牛蒡子、荆芥穗、淡豆豉、桔梗、淡竹叶、芦根、甘草','辛凉透表，清热解毒','温病初起(风热表证，发热口渴咽痛)','外感风寒者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('桑菊饮','《温病条辨》','桑叶、菊花、杏仁、连翘、薄荷、苦桔梗、生甘草、苇根','疏风清热，宣肺止咳','风温初起(但咳，身热不甚)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('麻杏石甘汤','《伤寒论》','麻黄、杏仁、炙甘草、石膏','辛凉疏表，清肺平喘','外感风邪、邪热壅肺证(身热不解、咳逆气急)','风寒实喘、虚喘者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('败毒散','《太平惠民和剂局方》','柴胡、前胡、川芎、枳壳、羌活、独活、茯苓、桔梗、人参、甘草','散寒祛湿，益气解表','气虚外感风寒湿证','外感风热、阴虚者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('大承气汤','《伤寒论》','大黄、厚朴、枳实、芒硝','峻下热结','阳明腑实证(痞满燥实)','表证未解、孕妇、体虚者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('大黄牡丹汤','《金匮要略》','大黄、牡丹皮、桃仁、冬瓜子、芒硝','泻热破瘀，散结消肿','肠痈初起(湿热瘀滞)','肠痈溃后及老人、孕妇、体虚者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('温脾汤','《备急千金要方》','大黄、当归、干姜、附子、人参、芒硝、甘草','攻下冷积，温补脾阳','阳虚寒积证','里实热结者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('麻子仁丸','《伤寒论》','麻子仁、芍药、枳实、大黄、厚朴、杏仁','润肠泄热，行气通便','脾约证(肠胃燥热、津液不足便秘)','孕妇及血虚津亏便秘者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('小柴胡汤','《伤寒论》','柴胡、黄芩、人参、半夏、炙甘草、生姜、大枣','和解少阳','少阳证(往来寒热、胸胁苦满、口苦咽干)','阴虚血少者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('逍遥散','《太平惠民和剂局方》','柴胡、当归、白芍、白术、茯苓、炙甘草、薄荷、生姜','疏肝解郁，养血健脾','肝郁血虚脾弱证(胁痛、神疲、月经不调)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('痛泻要方','《丹溪心法》','白术、白芍、陈皮、防风','补脾柔肝，祛湿止泻','脾虚肝旺之痛泻(肠鸣腹痛、泻后痛缓)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('半夏泻心汤','《伤寒论》','半夏、黄芩、干姜、人参、黄连、大枣、炙甘草','寒热平调，消痞散结','寒热互结之痞证(心下痞满、呕吐下利)','气滞或食积所致痞满者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('白虎汤','《伤寒论》','石膏、知母、炙甘草、粳米','清热生津','气分热盛证(壮热面赤、烦渴、大汗、脉洪大)','表证未解、无汗发热、脾胃虚寒者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('清营汤','《温病条辨》','犀角(水牛角代)、生地黄、玄参、竹叶心、麦冬、丹参、黄连、金银花、连翘','清营解毒，透热养阴','热入营分证(身热夜甚、神烦少寐、斑疹隐隐)','湿温病、舌苔白腻者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('犀角地黄汤','《外台秘要》','犀角(水牛角代)、生地黄、芍药、牡丹皮','清热解毒，凉血散瘀','热入血分证(吐衄发斑、神昏谵语)','阳虚失血、脾胃虚弱者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('黄连解毒汤','《外台秘要》引崔氏方','黄连、黄芩、黄柏、栀子','泻火解毒','三焦火毒热盛证(大热烦躁、吐衄发斑、痈肿疔毒)','非火盛者及津液受损者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('普济消毒饮','《东垣试效方》','黄芩、黄连、陈皮、甘草、玄参、柴胡、桔梗、连翘、板蓝根、马勃、牛蒡子、薄荷、僵蚕、升麻','清热解毒，疏风散邪','大头瘟(风热疫毒上攻头面)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('仙方活命饮','《校注妇人良方》','金银花、防风、白芷、当归尾、陈皮、皂角刺、穿山甲、天花粉、乳香、没药、贝母、赤芍、甘草','清热解毒，消肿溃坚，活血止痛','阳证痈疡肿毒初起','痈疡已溃、阴证疮疡忌用，脾胃虚寒者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('龙胆泻肝汤','《医方集解》','龙胆、黄芩、栀子、泽泻、木通、车前子、当归、生地黄、柴胡、甘草','清泻肝胆实火，清利肝经湿热','肝胆实火上炎/肝经湿热下注证','脾胃虚寒、阴虚阳亢者慎用，不宜久服');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('清胃散','《脾胃论》','生地黄、当归身、牡丹皮、黄连、升麻','清胃凉血','胃火炽盛证(牙痛牵引头脑、面颊发热、牙宣出血)','风寒牙痛、肾虚火炎牙痛者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('玉女煎','《景岳全书》','石膏、熟地黄、麦冬、知母、牛膝','清胃热，滋肾阴','胃热阴虚证(烦热干渴、牙痛齿松)','脾虚便溏者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('芍药汤','《素问病机气宜保命集》','芍药、当归、黄连、槟榔、木香、甘草、大黄、黄芩、官桂','清热燥湿，调气和血','湿热痢疾(腹痛便脓血、里急后重)','虚寒痢疾者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('白头翁汤','《伤寒论》','白头翁、黄柏、黄连、秦皮','清热解毒，凉血止痢','热毒痢疾(下痢脓血、赤多白少、里急后重)','虚寒痢疾者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('青蒿鳖甲汤','《温病条辨》','青蒿、鳖甲、生地黄、知母、牡丹皮','养阴透热','温病后期、邪伏阴分证(夜热早凉、热退无汗)','阴虚欲作动风者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('清暑益气汤','《温热经纬》','西洋参、石斛、麦冬、黄连、竹叶、荷梗、知母、甘草、粳米、西瓜翠衣','清暑益气，养阴生津','暑热气津两伤证','暑病夹湿者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('理中丸','《伤寒论》','人参、干姜、白术、炙甘草','温中祛寒，补气健脾','脾胃虚寒证/阳虚失血/脾胃虚寒所致胸痹、小儿慢惊','湿热内蕴中焦者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('小建中汤','《伤寒论》','桂枝、炙甘草、大枣、芍药、生姜、胶饴','温中补虚，和里缓急','中焦虚寒、肝脾失调、阴阳不和证(虚劳里急腹痛)','阴虚火旺者忌用，呕家、吐蛔者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('吴茱萸汤','《伤寒论》','吴茱萸、人参、生姜、大枣','温中补虚，降逆止呕','胃中虚寒/肝寒上逆/肾寒上逆之呕吐','胃热呕吐、阴虚呕吐者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('四逆汤','《伤寒论》','附子、干姜、炙甘草','回阳救逆','心肾阳衰寒厥证(四肢厥逆、恶寒蜷卧、吐利腹痛)','真热假寒者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('当归四逆汤','《伤寒论》','当归、桂枝、芍药、细辛、炙甘草、通草、大枣','温经散寒，养血通脉','血虚寒厥证(手足厥寒、肢体疼痛)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('阳和汤','《外科证治全生集》','熟地黄、麻黄、鹿角胶、白芥子、肉桂、生甘草、炮姜炭','温阳补血，散寒通滞','阴疽(贴骨疽、脱疽、流注、鹤膝风等)','阳证疮疡红肿热痛、阴虚有热者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('四君子汤','《太平惠民和剂局方》','人参、白术、茯苓、炙甘草','益气健脾','脾胃气虚证(面色萎白、食少便溏、乏力)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('参苓白术散','《太平惠民和剂局方》','人参、白术、茯苓、甘草、山药、莲子肉、白扁豆、薏苡仁、砂仁、桔梗、大枣','益气健脾，渗湿止泻','脾虚湿盛证(食少便溏、咳嗽痰多)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('补中益气汤','《内外伤辨惑论》','黄芪、炙甘草、人参、当归、橘皮、升麻、柴胡、白术','补中益气，升阳举陷','脾虚气陷证/气虚发热证(久泻脱肛、子宫脱垂)','阴虚火旺及实证发热者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('玉屏风散','《医方类聚》','防风、黄芪、白术','益气固表止汗','表虚自汗(易感风邪)','阴虚盗汗者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('四物汤','《仙授理伤续断秘方》','熟地黄、当归、白芍、川芎','补血调血','营血虚滞证(头晕心悸、月经不调)','湿盛中满、大便溏泄者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('当归补血汤','《内外伤辨惑论》','黄芪、当归','补气生血','血虚阳浮发热证/疮疡溃后久不愈合','阴虚潮热者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('归脾汤','《正体类要》','白术、人参、黄芪、当归、甘草、茯苓、远志、酸枣仁、木香、龙眼肉、生姜、大枣','益气补血，健脾养心','心脾气血两虚证/脾不统血证',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('八珍汤','《正体类要》','人参、白术、白茯苓、当归、川芎、白芍药、熟地黄、炙甘草','益气补血','气血两虚证',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('炙甘草汤','《伤寒论》','炙甘草、生姜、桂枝、人参、生地黄、阿胶、麦冬、麻仁、大枣','滋阴养血，益气温阳，复脉定悸','阴血不足、阳气虚弱证(脉结代、心动悸)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('六味地黄丸','《小儿药证直诀》','熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓','填精滋阴补肾','肾阴亏虚证(腰膝酸软、头晕目眩、盗汗遗精)','脾虚泄泻者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('左归丸','《景岳全书》','熟地黄、山药、山茱萸、枸杞子、菟丝子、鹿角胶、龟板胶、川牛膝','滋阴补肾，填精益髓','真阴不足证','脾虚泄泻者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('大补阴丸','《丹溪心法》','熟地黄、龟板、黄柏、知母、猪脊髓','滋阴降火','阴虚火旺证(骨蒸潮热、盗汗遗精、咳嗽咯血)','脾胃虚弱、食少便溏者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('百合固金汤','《慎斋遗书》','百合、熟地黄、生地黄、当归、白芍、甘草、桔梗、玄参、贝母、麦冬','滋养肺肾，止咳化痰','肺肾阴亏、虚火上炎证(咳嗽气喘、痰中带血)','脾虚便溏者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('肾气丸','《金匮要略》','干地黄、山药、山茱萸、泽泻、茯苓、牡丹皮、桂枝、附子','补肾助阳','肾阳不足证(腰痛脚软、小便不利或反多)','阴虚火旺者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('右归丸','《景岳全书》','熟地黄、山药、山茱萸、枸杞子、菟丝子、鹿角胶、杜仲、肉桂、当归、制附子','温补肾阳，填精益髓','肾阳不足、命门火衰证','阴虚火旺者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('地黄饮子','《圣济总录》','熟干地黄、巴戟天、山茱萸、石斛、肉苁蓉、附子、五味子、官桂、白茯苓、麦冬、石菖蒲、远志','滋肾阴，补肾阳，开窍化痰','喑痱证(舌强不能言、足废不能用)','气火上升、肝阳偏亢者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('一贯煎','《续名医类案》','北沙参、麦冬、当归身、生地黄、枸杞子、川楝子','滋阴疏肝','肝肾阴虚、肝气郁滞证(胸脘胁痛、吞酸吐苦)','停痰积饮者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('牡蛎散','《太平惠民和剂局方》','黄芪、麻黄根、牡蛎、小麦','敛阴止汗，益气固表','体虚自汗、盗汗证','阴虚火旺之盗汗宜配滋阴降火药');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('九仙散','《卫生宝鉴》引王子昭方','人参、款冬花、桑白皮、桔梗、五味子、阿胶、乌梅、贝母、罂粟壳','敛肺止咳，益气养阴','久咳伤肺、气阴两虚证','罂粟壳有毒，不宜久服，外感咳嗽者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('真人养脏汤','《太平惠民和剂局方》','人参、当归、白术、肉豆蔻、肉桂、炙甘草、白芍、木香、诃子、罂粟壳','涩肠固脱，温补脾肾','久泻久痢、脾肾虚寒证','罂粟壳有毒，不宜久服，湿热积滞泻痢者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('四神丸','《证治准绳》','肉豆蔻、补骨脂、五味子、吴茱萸、生姜、红枣','温肾暖脾，固肠止泻','脾肾阳虚之五更泻','湿热泻痢者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('金锁固精丸','《医方集解》','沙苑子、芡实、莲须、龙骨、牡蛎、莲子','补肾涩精','肾虚不固之遗精滑泄','湿热下注所致遗精者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('固冲汤','《医学衷中参西录》','白术、生黄芪、龙骨、牡蛎、山茱萸、生白芍、海螵蛸、茜草、棕榈炭、五倍子','益气健脾，固冲摄血','脾肾亏虚、冲脉不固之崩漏','血热妄行之崩漏者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('天王补心丹','《校注妇人良方》','生地黄、人参、丹参、玄参、白茯苓、五味子、远志、桔梗、当归、天门冬、麦门冬、柏子仁、酸枣仁、朱砂','滋阴养血，补心安神','阴虚血少、神志不安证(心悸失眠、梦遗健忘)','朱砂有毒，不宜久服，脾胃虚寒者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('酸枣仁汤','《金匮要略》','酸枣仁、甘草、知母、茯苓、川芎','养血安神，清热除烦','肝血不足、虚热内扰之虚烦不眠',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('甘麦大枣汤','《金匮要略》','甘草、小麦、大枣','养心安神，和中缓急','脏躁(精神恍惚、悲伤欲哭、数欠伸)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('安宫牛黄丸','《温病条辨》','牛黄、麝香、犀角(水牛角浓缩粉代)、黄连、黄芩、栀子、冰片、郁金、朱砂、珍珠、雄黄、金箔','清热解毒，豁痰开窍','邪热内陷心包证(高热烦躁、神昏谵语、中风昏迷)','寒闭证、脱证忌用，含朱砂雄黄不宜久服，孕妇慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('紫雪','《外台秘要》','石膏、寒水石、磁石、滑石、犀角(代)、羚羊角(代)、木香、沉香、玄参、升麻、甘草、丁香、朴硝、硝石、麝香、朱砂、黄金','清热开窍，息风止痉','温热病、热闭心包及热盛动风证(高热神昏、痉厥)','虚风内动、脱证忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('至宝丹','《灵苑方》','犀角(代)、朱砂、雄黄、玳瑁、琥珀、麝香、龙脑、牛黄、安息香、金箔、银箔','清热开窍，化浊解毒','痰热内闭心包证(神昏谵语、身热烦躁、痰盛气粗)','寒闭、脱证及孕妇忌用，含朱砂雄黄不宜久服');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('苏合香丸','《太平惠民和剂局方》','苏合香、麝香、安息香、冰片、香附、檀香、丁香、沉香、木香、乳香、荜茇、白术、诃子、朱砂、犀角(代)','温通开窍，行气止痛','寒闭证(突然昏倒、牙关紧闭、不省人事)及寒凝气滞之心腹猝痛','热闭、脱证及孕妇忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('越鞠丸','《丹溪心法》','香附、川芎、苍术、栀子、神曲','行气解郁','六郁证(气、血、痰、火、湿、食郁，胸膈痞闷)','阴虚火旺者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('柴胡疏肝散','《医学统旨》','柴胡、陈皮、川芎、香附、枳壳、芍药、甘草','疏肝行气，活血止痛','肝气郁滞证(胁肋疼痛、寒热往来)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('瓜蒌薤白白酒汤','《金匮要略》','瓜蒌实、薤白、白酒','通阳散结，行气祛痰','胸阳不振、痰气互结之胸痹(胸背痛、短气)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('半夏厚朴汤','《金匮要略》','半夏、厚朴、茯苓、生姜、苏叶','行气散结，降逆化痰','梅核气(咽中如有物阻、咯吐不出、吞咽不下)','气郁化火、阴伤津少者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('枳实薤白桂枝汤','《金匮要略》','枳实、厚朴、薤白、桂枝、瓜蒌实','通阳散结，祛痰下气','胸阳不振、痰气互结而气逆较甚之胸痹',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('天台乌药散','《圣济总录》(《医学发明》引)','乌药、木香、小茴香、青皮、高良姜、槟榔、川楝子、巴豆','行气疏肝，散寒止痛','寒凝气滞之小肠疝气(少腹引控睾丸而痛)','湿热下注之疝痛不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('暖肝煎','《景岳全书》','当归、枸杞子、小茴香、肉桂、乌药、沉香、茯苓','温补肝肾，行气止痛','肝肾不足、寒滞肝脉之疝气、少腹疼痛','湿热下注、阴囊红肿热痛者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('苏子降气汤','《太平惠民和剂局方》','紫苏子、半夏、川当归、甘草、前胡、厚朴、肉桂、生姜、大枣、苏叶','降气平喘，祛痰止咳','上实下虚之喘咳证(痰涎壅盛、喘咳短气、腰酸脚软)','痰热咳喘、阴虚喘咳者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('定喘汤','《摄生众妙方》','白果、麻黄、苏子、甘草、款冬花、杏仁、桑白皮、黄芩、法半夏','宣降肺气，清热化痰','风寒外束、痰热内蕴之哮喘(咳嗽痰多气急、痰稠色黄)','新感风寒、无汗而喘、内无痰热者及哮喘日久气虚者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('旋覆代赭汤','《伤寒论》','旋覆花、人参、生姜、代赭石、炙甘草、半夏、大枣','降逆化痰，益气和胃','胃虚痰阻气逆证(心下痞硬、噫气不除)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('橘皮竹茹汤','《金匮要略》','橘皮、竹茹、大枣、生姜、甘草、人参','降逆止呃，益气清热','胃虚有热之呃逆','胃寒呃逆者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('桃核承气汤','《伤寒论》','桃仁、大黄、桂枝、炙甘草、芒硝','逐瘀泻热','下焦蓄血证(少腹急结、小便自利、谵语烦渴)','孕妇及表证未解者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('血府逐瘀汤','《医林改错》','桃仁、红花、当归、生地黄、川芎、赤芍、牛膝、桔梗、柴胡、枳壳、甘草','活血化瘀，行气止痛','胸中血瘀证(胸痛头痛日久、痛如针刺有定处)','孕妇忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('补阳还五汤','《医林改错》','黄芪、当归尾、赤芍、地龙、川芎、红花、桃仁','补气活血通络','气虚血瘀之中风后遗症(半身不遂、口眼歪斜、语言謇涩)','中风后半身不遂属阴虚阳亢、痰阻血瘀者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('复元活血汤','《医学发明》','柴胡、瓜蒌根、当归、红花、甘草、穿山甲、大黄、桃仁','活血祛瘀，疏肝通络','跌打损伤、瘀血阻滞胁肋证','孕妇忌服，服药后以利为度');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('温经汤','《金匮要略》','吴茱萸、当归、芍药、川芎、人参、桂枝、阿胶、牡丹皮、生姜、甘草、半夏、麦冬','温经散寒，养血祛瘀','冲任虚寒、瘀血阻滞之月经不调、痛经、崩漏、不孕','实热瘀阻者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('生化汤','《傅青主女科》','全当归、川芎、桃仁、干姜、炙甘草(黄酒、童便)','养血祛瘀，温经止痛','血虚寒凝、瘀血阻滞之产后恶露不行、小腹冷痛','产后血热而有瘀滞者不宜，恶露过多、出血不止者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('桂枝茯苓丸','《金匮要略》','桂枝、茯苓、牡丹皮、桃仁、芍药','活血化瘀，缓消癥块','瘀阻胞宫之癥块(妇人宿有癥块、妊娠漏下、痛经闭经)','孕妇慎用，血虚无瘀者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('失笑散','《太平惠民和剂局方》','五灵脂、蒲黄','活血祛瘀，散结止痛','瘀血疼痛证(心腹刺痛、痛经、产后恶露不行)','孕妇忌用，脾胃虚弱者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('丹参饮','《时方歌括》','丹参、檀香、砂仁','活血祛瘀，行气止痛','血瘀气滞之心胃诸痛',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('十灰散','《十药神书》','大蓟、小蓟、荷叶、侧柏叶、白茅根、茜草根、栀子、大黄、牡丹皮、棕榈皮','凉血止血','血热妄行之上部出血(呕血、吐血、咯血、衄血)','虚寒性出血者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('咳血方','《丹溪心法》','青黛、瓜蒌仁、海粉、栀子、诃子、蜜、姜汁','清肝宁肺，凉血止血','肝火犯肺之咳血证(咳嗽痰稠带血、心烦易怒)','肺肾阴虚及脾虚便溏者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('小蓟饮子','《济生方》引《玉机微义》','生地黄、小蓟、滑石、木通、蒲黄、藕节、淡竹叶、当归、栀子、甘草','凉血止血，利水通淋','热结下焦之血淋、尿血','血淋日久正虚者及孕妇慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('槐花散','《普济本事方》','槐花、柏叶、荆芥穗、枳壳','清肠止血，疏风行气','风热湿毒、壅遏肠道之肠风、脏毒下血','便血日久属气虚或阴虚者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('黄土汤','《金匮要略》','甘草、干地黄、白术、附子、阿胶、黄芩、灶心黄土','温阳健脾，养血止血','脾阳不足、脾不统血之出血(便血、吐血、崩漏)','热证出血者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('川芎茶调散','《太平惠民和剂局方》','川芎、白芷、羌活、细辛、防风、荆芥、薄荷、甘草','疏风止痛','外感风邪头痛(偏正头痛或巅顶作痛、恶寒发热)','久病气虚、血虚或肝肾不足之头痛不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('独活寄生汤','《备急千金要方》','独活、桑寄生、杜仲、牛膝、细辛、秦艽、茯苓、肉桂心、防风、川芎、人参、甘草、当归、芍药、干地黄','祛风湿，止痹痛，益肝肾，补气血','痹证日久、肝肾两虚、气血不足证(腰膝疼痛、肢节屈伸不利)','湿热痹证者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('大秦艽汤','《素问病机气宜保命集》','秦艽、甘草、川芎、当归、白芍、细辛、羌活、防风、黄芩、石膏、白芷、白术、生地黄、熟地黄、白茯苓、独活','祛风清热，养血活血','风邪初中经络证(口眼歪斜、舌强不能言语、肢体不能运动)','内风所致者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('牵正散','《杨氏家藏方》','白附子、僵蚕、全蝎','祛风化痰，通络止痉','风中头面经络之口眼歪斜','白附子、全蝎有毒，用量宜慎，气虚血瘀或肝风内动之口眼歪斜不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('玉真散','《外科正宗》','南星、防风、白芷、天麻、羌活、白附子','祛风化痰，定搐止痉','破伤风(牙关紧闭、口撮唇紧、身体强直、角弓反张)','方中白附子、南星有毒，孕妇忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('小活络丹','《太平惠民和剂局方》','川乌、草乌、地龙、天南星、乳香、没药','祛风除湿，化痰通络，活血止痛','风寒湿痹(肢体筋脉疼痛、麻木拘挛、关节屈伸不利)','川乌草乌南星有毒，阴虚有热及孕妇忌用，不宜过量');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('镇肝熄风汤','《医学衷中参西录》','怀牛膝、代赭石、龙骨、牡蛎、龟板、白芍、玄参、天冬、川楝子、麦芽、茵陈、甘草','镇肝息风，滋阴潜阳','类中风(肝肾阴亏、肝阳上亢、气血逆乱，头目眩晕、目胀耳鸣、脑中热痛)','气虚血瘀之中风后遗症者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('天麻钩藤饮','《中医内科新编》','天麻、钩藤、石决明、栀子、黄芩、川牛膝、杜仲、益母草、桑寄生、夜交藤、朱茯神','平肝息风，清热活血，补益肝肾','肝阳偏亢、肝风上扰证(头痛眩晕、失眠抽搐)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('大定风珠','《温病条辨》','生白芍、阿胶、生龟板、干地黄、麻仁、五味子、生牡蛎、麦冬、炙甘草、鸡子黄、鳖甲','滋阴息风','阴虚风动证(手足瘛疭、形消神倦、脉气虚弱、舌绛苔少)','阴液未亏、邪热尚盛者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('阿胶鸡子黄汤','《通俗伤寒论》','阿胶、白芍、石决明、钩藤、生地黄、炙甘草、生牡蛎、络石藤、茯神、鸡子黄','滋阴养血，柔肝息风','邪热久羁、阴血不足、虚风内动证',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('清燥救肺汤','《医门法律》','桑叶、石膏、甘草、人参、胡麻仁、阿胶、麦门冬、杏仁、枇杷叶','清燥润肺，养阴益气','温燥伤肺之重证(身热头痛、干咳无痰、气逆而喘)','脾虚痰湿者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('杏苏散','《温病条辨》','苏叶、半夏、茯苓、前胡、苦桔梗、枳壳、甘草、生姜、橘皮、杏仁、大枣','清宣凉燥，理肺化痰','外感凉燥证(头微痛、恶寒无汗、咳嗽痰稀)','外感温燥者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('桑杏汤','《温病条辨》','桑叶、杏仁、沙参、象贝、豆豉、栀子皮、梨皮','清宣温燥，润肺止咳','外感温燥证(身不甚热、干咳无痰或痰少而黏、口渴)','凉燥者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('麦门冬汤','《金匮要略》','麦门冬、半夏、人参、甘草、粳米、大枣','滋养肺胃，降逆下气','虚热肺痿/胃阴不足证(咳唾涎沫、气喘短气、气逆呕吐)','寒痰壅肺之咳逆、脾胃虚寒之呕吐者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('养阴清肺汤','《重楼玉钥》','大生地黄、麦冬、生甘草、玄参、贝母、牡丹皮、薄荷、白芍','养阴清肺，解毒利咽','白喉之阴虚燥热证(喉间起白膜、咽喉肿痛、鼻干唇燥)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('百合固金汤(肺痨)','《慎斋遗书》','百合、麦冬、玄参、生地黄、熟地黄、当归、白芍、贝母、桔梗、甘草','滋肾保肺，止咳化痰','肺肾阴亏、虚火上炎之肺痨、咳嗽','脾虚便溏者慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('平胃散','《太平惠民和剂局方》','苍术、厚朴、陈皮、甘草、生姜、大枣','燥湿运脾，行气和胃','湿滞脾胃证(脘腹胀满、不思饮食、口淡无味、呕恶便溏)','阴虚气滞、脾胃虚弱者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('藿香正气散','《太平惠民和剂局方》','藿香、紫苏、白芷、大腹皮、茯苓、白术、陈皮、厚朴、半夏曲、桔梗、甘草、生姜、大枣','解表化湿，理气和中','外感风寒、内伤湿滞证(霍乱吐泻、恶寒发热、脘腹疼痛)','湿热霍乱及暑热感冒者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('茵陈蒿汤','《伤寒论》','茵陈蒿、栀子、大黄','清热，利湿，退黄','湿热黄疸(阳黄，一身面目俱黄、黄色鲜明、腹微满、口渴)','阴黄者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('八正散','《太平惠民和剂局方》','车前子、瞿麦、萹蓄、滑石、山栀子仁、炙甘草、木通、大黄、灯心','清热泻火，利水通淋','湿热淋证(尿频尿急、尿时涩痛、淋沥不畅、尿色浑赤)','劳淋、膏淋及孕妇不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('三仁汤','《温病条辨》','杏仁、飞滑石、白通草、白蔻仁、竹叶、厚朴、生薏苡仁、半夏','宣畅气机，清利湿热','湿温初起及暑温夹湿之湿重于热证','热重于湿者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('甘露消毒丹','《医效秘传》引叶天士方','飞滑石、绵茵陈、淡黄芩、石菖蒲、川贝母、木通、藿香、射干、连翘、白蔻仁、薄荷','利湿化浊，清热解毒','湿温时疫、邪在气分、湿热并重证','湿重于热者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('连朴饮','《霍乱论》','制厚朴、川连、石菖蒲、制半夏、香豉、焦栀子、芦根','清热化湿，理气和中','湿热霍乱(上吐下泻、胸脘痞闷、小便短赤)','寒湿霍乱者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('二妙散','《丹溪心法》','黄柏、苍术','清热燥湿','湿热下注证(筋骨疼痛、两足痿软、足膝红肿、湿热带下、下部湿疮)','寒湿为患者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('五苓散','《伤寒论》','猪苓、泽泻、白术、茯苓、桂枝','利水渗湿，温阳化气','膀胱气化不利之蓄水证(小便不利、头痛微热、烦渴欲饮、水入即吐)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('猪苓汤','《伤寒论》','猪苓、茯苓、泽泻、阿胶、滑石','利水，养阴，清热','水热互结证(小便不利、发热、口渴欲饮、心烦不寐、咳嗽呕恶)','内热盛、阴津大亏者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('防己黄芪汤','《金匮要略》','防己、黄芪、甘草、白术、生姜、大枣','益气祛风，健脾利水','表虚不固之风水或风湿证(汗出恶风、身重、小便不利、舌淡苔白)','水湿壅盛而汗不出者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('苓桂术甘汤','《金匮要略》','茯苓、桂枝、白术、炙甘草','温阳化饮，健脾利湿','中阳不足之痰饮(胸胁支满、目眩心悸、短气而咳)','饮邪化热、咳痰黏稠者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('真武汤','《伤寒论》','茯苓、芍药、白术、生姜、附子','温阳利水','阳虚水泛证(小便不利、肢体沉重或浮肿、腹痛下利、心悸头眩)','湿热内停之水肿者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('实脾散','《重订严氏济生方》','厚朴、白术、木瓜、木香、草果仁、大腹子、附子、白茯苓、干姜、炙甘草、生姜、大枣','温阳健脾，行气利水','脾肾阳虚、水气内停之阴水(身半以下肿甚、手足不温、口中不渴、便溏)','阳水实证者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('萆薢分清饮','《杨氏家藏方》','益智仁、川萆薢、石菖蒲、乌药、盐','温肾利湿，分清化浊','下焦虚寒之膏淋、白浊(小便频数、浑浊不清、白如米泔)','湿热白浊者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('羌活胜湿汤','《脾胃论》','羌活、独活、藁本、防风、炙甘草、川芎、蔓荆子','祛风，胜湿，止痛','风湿在表之痹证(肩背痛不可回顾、头痛身重、腰脊疼痛)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('二陈汤','《太平惠民和剂局方》','半夏、橘红、白茯苓、炙甘草、生姜、乌梅','燥湿化痰，理气和中','湿痰证(咳嗽痰多、色白易咯、恶心呕吐、胸膈痞闷)','阴虚燥咳、劳痰咯血者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('温胆汤','《三因极一病证方论》','半夏、竹茹、枳实、陈皮、炙甘草、茯苓、生姜、大枣','理气化痰，和胃利胆','胆郁痰扰证(胆怯易惊、虚烦不寐、呕恶呃逆、眩晕癫痫)','心肝血虚之失眠者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('茯苓丸','《是斋百一选方》引《全生指迷方》','茯苓、枳壳、半夏、风化朴硝、生姜','燥湿行气，软坚化痰','痰伏中脘、流注经络证(两臂酸痛或抽掣、两手发麻)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('清气化痰丸','《医方考》','胆南星、瓜蒌仁、黄芩、枳实、陈皮、茯苓、苦杏仁、半夏','清热化痰，理气止咳','痰热咳嗽(咳嗽气喘、咯痰黄稠、胸膈痞满)','寒痰、湿痰者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('小陷胸汤','《伤寒论》','黄连、半夏、瓜蒌实','清热化痰，宽胸散结','痰热互结之小结胸证(胸脘痞闷、按之则痛、咳痰黄稠)','湿痰、寒痰者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('滚痰丸','《泰定养生主论》录王隐君方','大黄、黄芩、礞石、沉香','泻火逐痰','实热老痰证(癫狂惊悸、怔忡昏迷、咳喘痰稠、胸脘痞闷、眩晕痰多)','虚人、孕妇及脾胃虚寒者忌用，药性峻猛不可久服');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('贝母瓜蒌散','《医学心悟》','贝母、瓜蒌、天花粉、茯苓、橘红、桔梗','润肺清热，理气化痰','燥痰咳嗽(咯痰不爽、涩而难出、咽喉干燥哽痛)','湿痰、寒痰者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('苓甘五味姜辛汤','《金匮要略》','茯苓、甘草、干姜、细辛、五味子','温肺化饮','寒饮咳嗽(咳嗽痰多、清稀色白、胸膈痞满)','肺燥有热、阴虚咳嗽者忌用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('三子养亲汤','《韩氏医通》','紫苏子、白芥子、莱菔子','温肺化痰，降气消食','痰壅气逆食滞证(咳嗽喘逆、痰多胸痞、食少难消)','气虚久咳、脾虚便溏者不宜单用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('保和丸','《丹溪心法》','山楂、神曲、半夏、茯苓、陈皮、连翘、莱菔子','消食和胃','食积证(脘腹痞满胀痛、嗳腐吞酸、恶食呕逆、大便泄泻)','脾虚食滞者不宜单用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('枳实导滞丸','《内外伤辨惑论》','大黄、枳实、神曲、茯苓、黄芩、黄连、白术、泽泻','消导化积，清热利湿','湿热食积证(脘腹胀痛、下痢泄泻、小便短赤)','虚寒痢疾者不宜');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('健脾丸','《证治准绳》','白术、木香、黄连、甘草、白茯苓、人参、神曲、陈皮、砂仁、麦芽、山楂、山药、肉豆蔻','健脾和胃，消食止泻','脾虚食积证(食少难消、脘腹痞闷、大便溏薄)',NULL);
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('肥儿丸','《太平惠民和剂局方》','神曲、黄连、肉豆蔻、使君子、麦芽、槟榔、木香、猪胆汁','健脾消积，清热驱虫','小儿疳积(面黄体瘦、肚腹胀大、发热口臭、便溏虫积)','脾胃虚弱者不宜久服');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('乌梅丸','《伤寒论》','乌梅、细辛、干姜、黄连、当归、附子、蜀椒、桂枝、人参、黄柏','温脏安蛔','蛔厥证(腹痛时作、烦闷呕吐、常自吐蛔、手足厥冷)，亦治久利久泻','孕妇慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('化虫丸','《太平惠民和剂局方》','铅粉(现多不用)、鹤虱、槟榔、苦楝根皮、白矾','杀肠中诸虫','肠中诸虫(发作时腹中疼痛、往来上下、呕吐清水涎沫)','铅粉有毒，现代已少用，体虚及孕妇慎用');
INSERT INTO knowledge.tcm_formulas(formula_name,source,composition,effects,indications,caution) VALUES ('布袋丸','《补要袖珍小儿方论》','夜明砂、芜荑、使君子、白茯苓、白术、人参、甘草、芦荟','驱蛔消疳，补养脾胃','小儿虫疳(体热面黄、肢细腹大、发焦目暗)',NULL);
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中府','手太阴肺经','胸前壁外上方，前正中线旁开6寸，平第1肋间隙','咳嗽、气喘、胸胀满、肩背痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('尺泽','手太阴肺经','肘横纹中，肱二头肌腱桡侧凹陷处','咳嗽、气喘、咯血、咽喉肿痛、肘臂挛痛、急性吐泻');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('孔最','手太阴肺经','前臂掌面桡侧，腕横纹上7寸，尺泽与太渊连线上','咯血、咳嗽、气喘、咽喉肿痛、痔血');
