INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('天枢','足阳明胃经','腹中部脐中旁开2寸','腹痛、腹胀、便秘、腹泻、痢疾、月经不调、痛经');
