INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('大肠俞','足太阳膀胱经','腰部第4腰椎棘突下旁开1.5寸','腰腿痛、腹痛、腹胀、肠鸣、泄泻、便秘');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('小肠俞','足太阳膀胱经','骶部第1骶椎棘突下旁开1.5寸','遗精、遗尿、尿血、白带、小腹胀痛、泄泻、痢疾、腰痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('膀胱俞','足太阳膀胱经','骶部第2骶椎棘突下旁开1.5寸','小便不利、遗尿、泄泻、便秘、腰脊强痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('次髎','足太阳膀胱经','骶部髂后上棘内下方，第2骶后孔中','疝气、月经不调、痛经、带下、小便不利、遗精、腰痛、下肢痿痹');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('委中','足太阳膀胱经','腘横纹中点，股二头肌腱与半腱肌腱中间','腰痛、下肢痿痹、中风昏迷、半身不遂、腹痛、急性吐泻、遗尿(四总穴)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('膏肓','足太阳膀胱经','背部第4胸椎棘突下旁开3寸','咳嗽、气喘、肺痨、健忘、遗精、盗汗、羸瘦虚损(保健灸)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('志室','足太阳膀胱经','腰部第2腰椎棘突下旁开3寸','遗精、阳痿、阴痛、小便不利、水肿、腰脊强痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('承筋','足太阳膀胱经','小腿后面合阳与承山连线中点，腓肠肌肌腹中央','痔疾、腰腿拘急疼痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('承山','足太阳膀胱经','小腿后面正中，委中与昆仑之间，伸直小腿或足跟上提时腓肠肌肌腹下尖角凹陷','痔疾、脚气、便秘、腰腿拘急疼痛、转筋');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('飞扬','足太阳膀胱经','小腿后面外踝后昆仑直上7寸，承山外下方1寸','头痛、目眩、鼻衄、腰腿疼痛、痔疾、癫狂');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('昆仑','足太阳膀胱经','足部外踝后方，外踝尖与跟腱之间凹陷','头痛、项强、目眩、鼻衄、癫痫、难产、腰骶疼痛、脚跟肿痛(孕妇慎用)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('申脉','足太阳膀胱经','足外侧部外踝直下方凹陷中','头痛、眩晕、癫狂痫、失眠、腰腿酸痛、目赤痛、眼睑下垂');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('至阴','足太阳膀胱经','足小趾末节外侧，距趾甲角0.1寸','头痛、鼻塞、鼻衄、目痛、胎位不正、难产(灸转胎)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('涌泉','足少阴肾经','足底部卷足时足前部凹陷处，约足底第2、3趾趾缝纹头与足跟连线前1/3','头顶痛、头晕、目眩、咽喉痛、舌干、失音、小便不利、便秘、昏厥、中暑、足心热');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('然谷','足少阴肾经','足内侧缘足舟骨粗隆下方赤白肉际','月经不调、阴挺、阴痒、遗精、消渴、泄泻、咳血、咽喉肿痛、足跗肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('太溪','足少阴肾经','足内侧内踝后方，内踝尖与跟腱之间凹陷','头痛目眩、咽喉肿痛、齿痛、耳聋、耳鸣、气喘、消渴、月经不调、遗精、阳痿、失眠、健忘、腰脊痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('大钟','足少阴肾经','足内侧内踝后下方，跟腱附着部内侧凹陷前下方','癃闭、遗尿、便秘、咯血、气喘、痴呆、嗜卧、腰脊强痛、足跟痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('水泉','足少阴肾经','足内侧内踝后下方，太溪直下1寸跟骨结节内侧凹陷','月经不调、痛经、阴挺、小便不利、目昏花');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('照海','足少阴肾经','足内侧内踝尖直下凹陷处','咽喉干燥、痫证、失眠、嗜卧、惊恐不宁、目赤肿痛、月经不调、痛经、小便频数、癃闭');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('复溜','足少阴肾经','小腿内侧太溪直上2寸，跟腱前方','泄泻、水肿、腹胀、腿肿、足痿、盗汗、热病汗不出、腰脊强痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('阴谷','足少阴肾经','腘窝内侧屈膝，半腱肌腱与半膜肌腱之间','阳痿、疝痛、月经不调、崩漏、小便不利、膝股内侧痛、癫狂');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('俞府','足少阴肾经','胸部锁骨下缘，前正中线旁开2寸','咳嗽、气喘、胸痛、呕吐、不嗜食');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('曲泽','手厥阴心包经','肘横纹中，肱二头肌腱尺侧凹陷','心痛、心悸、胃痛、呕吐、泄泻、热病、肘臂挛痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('郄门','手厥阴心包经','前臂掌侧腕横纹上5寸，曲泽与大陵连线上','心痛、心悸、胸痛、心烦、咳血、呕血、疔疮、癫痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('间使','手厥阴心包经','前臂掌侧腕横纹上3寸，掌长肌腱与桡侧腕屈肌腱之间','心痛、心悸、胃痛、呕吐、热病、癫狂痫、疟疾、臂痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('内关','手厥阴心包经','前臂掌侧腕横纹上2寸，掌长肌腱与桡侧腕屈肌腱之间','心痛、心悸、胸闷、胃痛、呕吐、呃逆、失眠、癫狂痫、眩晕、郁证');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('大陵','手厥阴心包经','腕掌横纹中点，掌长肌腱与桡侧腕屈肌腱之间','心痛、心悸、胃痛、呕吐、癫狂、疮疡、胸胁痛、腕关节痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('劳宫','手厥阴心包经','手掌心第2、3掌骨之间偏于第3掌骨，握拳屈指中指尖处','中风昏迷、中暑、心痛、癫狂痫、口疮、口臭、鹅掌风');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中冲','手厥阴心包经','手中指末节尖端中央','中风昏迷、舌强不语、中暑、昏厥、小儿惊风、热病、舌下肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('关冲','手少阳三焦经','手环指末节尺侧，距指甲角0.1寸','头痛、目赤、耳聋、耳鸣、咽喉肿痛、舌强、热病、昏厥');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中渚','手少阳三焦经','手背第4、5掌骨间，掌指关节后方凹陷处','头痛、目赤、耳聋、耳鸣、咽喉肿痛、热病、手指不能屈伸');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('阳池','手少阳三焦经','腕背横纹中，指总伸肌腱尺侧缘凹陷','腕痛、肩臂痛、耳聋、疟疾、消渴、口干');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('外关','手少阳三焦经','前臂背侧腕背横纹上2寸，尺骨与桡骨之间','热病、头痛、耳聋、耳鸣、胁肋痛、上肢痹痛、瘰疬');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('支沟','手少阳三焦经','前臂背侧腕背横纹上3寸，尺骨与桡骨之间','暴喑、耳聋、耳鸣、胁肋痛、呕吐、便秘、热病、瘰疬');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('会宗','手少阳三焦经','前臂背侧腕背横纹上3寸，支沟尺侧，尺骨桡侧缘','耳聋、痫证、上肢肌肤痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('肩髎','手少阳三焦经','肩髃后方，臂外展时肩峰后下方凹陷','臂痛、肩重不能举、胁肋疼痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('翳风','手少阳三焦经','耳垂后方，乳突与下颌骨边缘之间凹陷','耳鸣、耳聋、口眼歪斜、牙关紧闭、颊肿、瘰疬');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('角孙','手少阳三焦经','头部折耳廓向前，耳尖直上入发际处','耳部红肿、目赤肿痛、目翳、齿痛、颊肿、项强');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('耳门','手少阳三焦经','面部耳屏上切迹前方，下颌骨髁状突后缘，张口凹陷','耳聋、耳鸣、聤耳、齿痛、颈颔痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('丝竹空','手少阳三焦经','面部眉梢凹陷处','头痛、目眩、目赤痛、眼睑瞤动、齿痛、癫痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('瞳子髎','足少阳胆经','面部目外眦旁，眶外侧缘处','头痛、目赤肿痛、目翳、青盲、迎风流泪');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('听会','足少阳胆经','面部耳屏间切迹前方，下颌骨髁状突后缘，张口凹陷','耳鸣、耳聋、聤耳、齿痛、口眼歪斜、下颌脱臼');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('率谷','足少阳胆经','头部耳尖直上入发际1.5寸','头痛、眩晕、呕吐、小儿急慢惊风');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('完骨','足少阳胆经','头部耳后乳突后下方凹陷','头痛、颈项强痛、颊肿、齿痛、口歪、癫痫、疟疾');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('阳白','足少阳胆经','前额部瞳孔直上，眉上1寸','头痛、目眩、目痛、视物模糊、眼睑瞤动、面瘫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('头临泣','足少阳胆经','头部瞳孔直上入前发际0.5寸，神庭与头维连线中点','头痛、目眩、目赤痛、流泪、目翳、鼻塞、鼻渊、小儿惊痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('风池','足少阳胆经','项部枕骨之下，胸锁乳突肌与斜方肌上端之间凹陷','头痛、眩晕、颈项强痛、目赤痛、鼻渊、鼻衄、耳鸣、感冒、癫痫、中风');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('肩井','足少阳胆经','肩上大椎与肩峰端连线中点，肩部最高处','肩背痹痛、颈项强痛、上肢不遂、乳痈、难产、瘰疬(孕妇禁针)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('环跳','足少阳胆经','股外侧部侧卧屈股，股骨大转子最凸点与骶管裂孔连线外1/3与中1/3交点','腰胯疼痛、下肢痿痹、半身不遂、遍身风疹、挫闪腰痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('风市','足少阳胆经','大腿外侧部直立垂手中指尖处，髌底上7寸','中风半身不遂、下肢痿痹、麻木、遍身瘙痒、脚气');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('膝阳关','足少阳胆经','膝外侧阳陵泉上3寸，股骨外上髁上方凹陷','膝膑肿痛、腘筋挛急、小腿麻木');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('阳陵泉','足少阳胆经','小腿外侧腓骨头前下方凹陷','胁痛、口苦、呕吐、黄疸、膝肿痛、下肢痿痹、麻木、小儿惊风、破伤风(筋会)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('光明','足少阳胆经','小腿外侧外踝尖上5寸，腓骨前缘','目痛、夜盲、乳胀痛、膝痛、下肢痿痹、颊肿');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('悬钟(绝骨)','足少阳胆经','小腿外侧外踝尖上3寸，腓骨前缘','半身不遂、颈项强痛、胸腹胀满、胁痛、膝腿痛、脚气(髓会)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('丘墟','足少阳胆经','足外踝前下方，趾长伸肌腱外侧凹陷','胸腹胀满、下肢痿痹、外踝肿痛、疟疾、疝气、目赤肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('足临泣','足少阳胆经','足背外侧第4、5跖骨间，第4、5跖骨底结合部前方，小趾伸肌腱外侧凹陷','头痛、目外眦痛、目眩、乳痈、瘰疬、胁肋痛、疟疾、足跗肿痛、月经不调');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('侠溪','足少阳胆经','足背外侧第4、5趾间，趾蹼缘后方赤白肉际处','头痛、眩晕、惊悸、耳鸣、耳聋、目外眦赤痛、胁肋痛、乳痈、热病');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('足窍阴','足少阳胆经','第4趾末节外侧，距趾甲角0.1寸','偏头痛、目眩、目赤肿痛、耳聋、咽喉肿痛、热病、多梦、失眠、胁痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('大敦','足厥阴肝经','足大趾末节外侧，距趾甲角0.1寸','疝气、遗尿、经闭、崩漏、阴挺、癫痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('行间','足厥阴肝经','足背侧第1、2趾间，趾蹼缘后方赤白肉际处','月经过多、闭经、痛经、白带、遗尿、疝气、头痛、目赤肿痛、中风、癫痫、胁痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('太冲','足厥阴肝经','足背侧第1、2跖骨结合部前方凹陷','头痛、眩晕、目赤肿痛、口苦、胁痛、疝气、遗尿、崩漏、月经不调、癫痫、呕逆、下肢痿痹');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中封','足厥阴肝经','足背侧内踝前商丘与解溪连线之间，胫骨前肌腱内侧凹陷','疝气、遗精、小便不利、腹痛、内踝肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('蠡沟','足厥阴肝经','小腿内侧内踝尖上5寸，胫骨内侧面中央','小便不利、遗尿、月经不调、带下、下肢痿痹、睾丸肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中都','足厥阴肝经','小腿内侧内踝尖上7寸，胫骨内侧面中央','疝气、崩漏、腹痛、泄泻、恶露不尽');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('膝关','足厥阴肝经','小腿内侧胫骨内上髁后下方，阴陵泉后1寸，腓肠肌内侧头上部','膝膑肿痛、下肢痿痹、咽喉肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('曲泉','足厥阴肝经','膝内侧屈膝，膝关节内侧面横纹内侧端，股骨内侧髁后缘，半腱肌半膜肌止端前缘凹陷','月经不调、痛经、白带、阴挺、遗精、阳痿、疝气、小便不利、膝膑肿痛、癫狂');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('阴包','足厥阴肝经','大腿内侧股骨内上髁上4寸，股内肌与缝匠肌之间','月经不调、遗尿、小便不利、腰骶痛引小腹');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('章门','足厥阴肝经','侧腹部第11肋游离端下方','腹痛、腹胀、泄泻、胁痛、痞块、小儿疳积(脏会)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('期门','足厥阴肝经','胸部乳头直下第6肋间隙，前正中线旁开4寸','胸胁胀痛、呕吐、吞酸、呃逆、腹胀、泄泻、饥不欲食、乳痈');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('长强','督脉','会阴区尾骨端下0.5寸，尾骨端与肛门连线中点','泄泻、痢疾、便秘、便血、痔疮、癫狂痫、腰脊和尾骶部疼痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('腰阳关','督脉','腰部后正中线上第4腰椎棘突下凹陷中','腰骶疼痛、下肢痿痹、月经不调、遗精、阳痿、便血');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('命门','督脉','腰部后正中线上第2腰椎棘突下凹陷中','虚损腰痛、遗尿、泄泻、遗精、阳痿、早泄、赤白带下、月经不调、癫痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('至阳','督脉','背部后正中线上第7胸椎棘突下凹陷中','胸胁胀痛、黄疸、咳嗽、气喘、背痛、脊强');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('身柱','督脉','背部后正中线上第3胸椎棘突下凹陷中','咳嗽、气喘、癫痫、疔疮发背、脊背强痛、小儿惊风(保健灸)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('大椎','督脉','后正中线上第7颈椎棘突下凹陷中','热病、感冒、咳嗽、气喘、骨蒸盗汗、癫痫、头痛项强、风疹、疟疾、虚劳');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('风府','督脉','项部后发际正中直上1寸，枕外隆凸直下，两侧斜方肌之间凹陷','癫狂、痫证、癔症、中风不语、头痛、项强、目眩、鼻衄、咽喉肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('百会','督脉','头部前发际正中直上5寸，两耳尖连线中点','头痛、眩晕、中风不语、癫狂、痫证、癔症、健忘、不寐、脱肛、阴挺、久泻');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('上星','督脉','头部前发际正中直上1寸','头痛、目痛、鼻渊、鼻衄、热病、疟疾、癫狂');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('神庭','督脉','头部前发际正中直上0.5寸','头痛、眩晕、失眠、鼻渊、癫痫、惊悸、目赤肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('素髎','督脉','面部鼻尖正中央','鼻塞、鼻衄、鼻流清涕、惊厥、昏迷、新生儿窒息');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('水沟(人中)','督脉','面部人中沟上1/3与中1/3交点','昏迷、晕厥、癫狂痫、急慢惊风、鼻塞、面肿、牙关紧闭、闪挫腰痛(急救要穴)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('龈交','督脉','上唇内唇系带与上齿龈相接处','痔疮、口臭、鼻渊、癫狂、齿龈肿痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('会阴','任脉','会阴部男性阴囊根部与肛门连线中点，女性大阴唇后联合与肛门连线中点','小便不利、遗尿、遗精、阳痿、月经不调、阴痛、阴痒、痔疮、溺水窒息、昏迷');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中极','任脉','下腹部前正中线上脐中下4寸','遗尿、小便不利、癃闭、遗精、阳痿、月经不调、崩漏、带下、阴挺、不孕');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('关元','任脉','下腹部前正中线上脐中下3寸','中风脱证、虚劳、少腹疼痛、泄泻、遗尿、遗精、阳痿、月经不调、带下、不孕、痛经(保健灸要穴)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('气海','任脉','下腹部前正中线上脐中下1.5寸','腹痛、泄泻、便秘、遗尿、疝气、遗精、月经不调、经闭、虚脱、形体羸瘦(保健灸)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('神阙','任脉','腹中部脐中央','腹痛、泄泻、脱肛、水肿、虚脱、中风脱证(禁刺，多用隔盐/姜灸)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('下脘','任脉','上腹部前正中线上脐中上2寸','腹痛、腹胀、呕吐、泄泻、食谷不化、痞块');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('中脘','任脉','上腹部前正中线上脐中上4寸','胃痛、呕吐、吞酸、呃逆、腹胀、泄泻、黄疸、癫狂、失眠(腑会，胃之募)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('上脘','任脉','上腹部前正中线上脐中上5寸','胃痛、呕吐、呃逆、腹胀、癫痫、黄疸');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('巨阙','任脉','上腹部前正中线上脐中上6寸','胸痛、心痛、心悸、呕吐、吞酸、癫狂痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('鸠尾','任脉','上腹部前正中线上胸剑结合部下1寸','胸痛、呃逆、腹胀、癫痫');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('膻中','任脉','胸部前正中线上平第4肋间，两乳头连线中点','咳嗽、气喘、胸痛、心悸、乳少、呕吐、噎膈(气会，心包募)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('天突','任脉','颈部前正中线上胸骨上窝中央','咳嗽、哮喘、胸痛、咽喉肿痛、暴喑、瘿气、梅核气、噎膈');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('廉泉','任脉','颈部前正中线上结喉上方，舌骨上缘凹陷处','舌下肿痛、舌纵流涎、舌强不语、暴喑、吞咽困难、口舌生疮');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('承浆','任脉','面部颏唇沟正中凹陷处','口歪、齿龈肿痛、流涎、暴喑、癫狂、面肿');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('印堂','经外奇穴','前额部两眉头连线中点','头痛、眩晕、鼻渊、鼻衄、失眠、小儿惊风、产后血晕');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('太阳','经外奇穴','颞部眉梢与目外眦之间向后约一横指凹陷','头痛、目疾、面瘫、牙痛、急性扭伤');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('定喘','经外奇穴','背部第7颈椎棘突下旁开0.5寸','哮喘、咳嗽、落枕、肩背痛、荨麻疹');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('夹脊(华佗夹脊)','经外奇穴','背腰部第1胸椎至第5腰椎棘突下两侧，后正中线旁开0.5寸，每侧17穴','上胸部治心肺/上肢，下胸部治胃肠，腰部治腰腹及下肢');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('十宣','经外奇穴','手十指尖端距指甲游离缘0.1寸，左右共10穴','昏迷、晕厥、中暑、热病、小儿惊厥、咽喉肿痛(点刺出血)');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('四缝','经外奇穴','手第2至5指掌侧近端指间关节横纹中央，一侧4穴','小儿疳积、百日咳、小儿腹泻');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('八邪','经外奇穴','手背侧第1至5指间指蹼缘后方赤白肉际处，左右共8穴','手背肿痛、手指麻木、烦热、目痛、毒蛇咬伤');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('落枕(外劳宫)','经外奇穴','手背侧第2、3掌骨间，掌指关节后0.5寸凹陷','落枕、手臂肿痛、脐风、胃痛');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('腰痛点','经外奇穴','手背侧第2、3掌骨与第4、5掌骨之间，腕背横纹下约1寸','急性腰扭伤、手背红肿疼痛、小儿急慢惊风');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('膝眼(内/外)','经外奇穴','髌韧带两侧凹陷，内侧称内膝眼，外侧称犊鼻','膝关节痛、腿痛、脚气');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('胆囊穴','经外奇穴','小腿外侧上部阳陵泉直下1-2寸压痛处','急慢性胆囊炎、胆石症、胆道蛔虫症、下肢痿痹');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('阑尾穴','经外奇穴','小腿前侧上部犊鼻下5寸，胫骨前缘旁开一横指','急慢性阑尾炎、消化不良、下肢瘫痪、足下垂');
INSERT INTO knowledge.tcm_acupoints(acupoint,meridian,location,indications) VALUES ('八风','经外奇穴','足背侧第1至5趾间趾蹼缘后方赤白肉际处，左右共8穴','足跗肿痛、趾痛、毒蛇咬伤、脚气、头痛、牙痛、月经不调');
